{
	"$schema": "https://turborepo.com/schema.json",
	"boundaries": {
		"tags": {
			"app": {
				"dependents": {
					"deny": ["package", "lib"]
				}
			},
			"package": {
				"dependencies": {
					"deny": ["app", "lib"]
				}
			},
			"lib": {
				"dependencies": {
					"deny": ["app", "package"]
				}
			}
		}
	},
	"globalDependencies": [
		"bun.lock",
		"bunfig.toml",
		"tsconfig.base.json",
		".oxfmtrc.json",
		".oxlintrc.json"
	],
	"tasks": {
		"build": {
			"description": "Production Next.js build for each app; workspaces compile as source via transpilePackages.",
			"inputs": ["$TURBO_DEFAULT$", "!README.md"],
			"outputs": [".next/**", "!.next/cache/**"]
		},
		"build:debug": {
			"description": "Uncached Next.js build with prerender diagnostics for agents.",
			"cache": false,
			"outputs": []
		},
		"dev": {
			"description": "Persistent dev server behind a portless-named .localhost origin.",
			"cache": false,
			"persistent": true
		},
		"test": {
			"description": "Vitest behavioral tests beside the workspace that owns the behavior.",
			"outputs": []
		},
		"start": {
			"description": "Production server for a locally built app.",
			"cache": false,
			"persistent": true
		},
		"typecheck": {
			"description": "TypeScript 7 typecheck; Next.js apps run next typegen first.",
			"outputs": []
		}
	}
}
